import React, { useEffect, useState } from 'react';
import DashboardLayout from '../../components/layout/DashboardLayout';
import { eventAPI } from '../../utils/api';
import './AdminEvents.css';

const NAV_ITEMS = [
  { path: '/admin', label: 'Dashboard', icon: '🏠', end: true },
  { path: '/admin/events', label: 'Events', icon: '📅' },
  { path: '/admin/policies', label: 'Policies', icon: '📚' },
];

const INITIAL_FORM = {
  title: '',
  description: '',
  category: 'academic',
  location: '',
  startAt: '',
  endAt: '',
  registrationDeadline: '',
  capacity: 100,
  targetAudience: 'all',
};

export default function AdminEvents() {
  const [events, setEvents] = useState([]);
  const [form, setForm] = useState(INITIAL_FORM);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const data = await eventAPI.getEvents();
      setEvents(data);
      setError('');
    } catch (requestError) {
      setError(requestError.message || 'Failed to load events');
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  const handleCreate = async (event) => {
    event.preventDefault();
    setSaving(true);
    try {
      await eventAPI.createEvent(form);
      setForm(INITIAL_FORM);
      await fetchEvents();
      setError('');
    } catch (requestError) {
      setError(requestError.message || 'Failed to create event');
    }
    setSaving(false);
  };

  const handleExport = async (eventItem) => {
    try {
      const blob = await eventAPI.exportAttendance(eventItem._id);
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `${eventItem.title.replace(/[^a-z0-9]+/gi, '-').toLowerCase()}-attendance.csv`;
      document.body.appendChild(anchor);
      anchor.click();
      document.body.removeChild(anchor);
      URL.revokeObjectURL(url);
    } catch (requestError) {
      setError(requestError.message || 'Failed to export attendance');
    }
  };

  return (
    <DashboardLayout navItems={NAV_ITEMS}>
      <div className="page-header">
        <h1 className="page-title">Event Management</h1>
        <p className="page-subtitle">Create events, monitor registrations, and export attendance.</p>
      </div>

      {error && <div className="alert alert-error">❌ {error}</div>}

      <form className="card admin-event-form" onSubmit={handleCreate}>
        <div className="admin-event-grid">
          <input
            className="form-input"
            placeholder="Event title"
            value={form.title}
            onChange={(event) => setForm((previous) => ({ ...previous, title: event.target.value }))}
            required
          />
          <select
            className="form-select"
            value={form.category}
            onChange={(event) => setForm((previous) => ({ ...previous, category: event.target.value }))}
          >
            <option value="academic">Academic</option>
            <option value="club">Club</option>
            <option value="placement">Placement</option>
            <option value="admin">Admin</option>
          </select>
          <input
            className="form-input"
            placeholder="Location"
            value={form.location}
            onChange={(event) => setForm((previous) => ({ ...previous, location: event.target.value }))}
            required
          />
          <input
            className="form-input"
            type="datetime-local"
            value={form.startAt}
            onChange={(event) => setForm((previous) => ({ ...previous, startAt: event.target.value }))}
            required
          />
          <input
            className="form-input"
            type="datetime-local"
            value={form.endAt}
            onChange={(event) => setForm((previous) => ({ ...previous, endAt: event.target.value }))}
          />
          <input
            className="form-input"
            type="datetime-local"
            value={form.registrationDeadline}
            onChange={(event) => setForm((previous) => ({ ...previous, registrationDeadline: event.target.value }))}
          />
          <input
            className="form-input"
            type="number"
            min={1}
            value={form.capacity}
            onChange={(event) => setForm((previous) => ({ ...previous, capacity: Number(event.target.value) }))}
          />
          <select
            className="form-select"
            value={form.targetAudience}
            onChange={(event) => setForm((previous) => ({ ...previous, targetAudience: event.target.value }))}
          >
            <option value="all">All users</option>
            <option value="students">Students only</option>
            <option value="admins">Admins only</option>
          </select>
        </div>
        <textarea
          className="form-textarea"
          placeholder="Event description"
          value={form.description}
          onChange={(event) => setForm((previous) => ({ ...previous, description: event.target.value }))}
          rows={4}
          required
        />
        <button className="btn btn-primary" type="submit" disabled={saving}>
          {saving ? 'Creating...' : 'Create Event'}
        </button>
      </form>

      {loading ? (
        <div className="card">
          <div className="empty-state">
            <div className="spinner" style={{ marginBottom: 16 }} />
            <h3>Loading events...</h3>
          </div>
        </div>
      ) : (
        <div className="card" style={{ overflow: 'hidden' }}>
          <table className="data-table">
            <thead>
              <tr>
                <th>Title</th>
                <th>Category</th>
                <th>When</th>
                <th>Registrations</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {events.map((event) => (
                <tr key={event._id}>
                  <td>
                    <strong>{event.title}</strong>
                    <div style={{ fontSize: '0.82rem', color: '#6b7491' }}>{event.location}</div>
                  </td>
                  <td style={{ textTransform: 'capitalize' }}>{event.category}</td>
                  <td>{new Date(event.startAt).toLocaleString('en-GB')}</td>
                  <td>{event.attendeeCount}/{event.capacity}</td>
                  <td>
                    <button className="btn btn-ghost btn-sm" onClick={() => handleExport(event)}>
                      Export CSV
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </DashboardLayout>
  );
}
